window.kbPageData["views/entry/k-ac573a06199ca0ed"] = {"key":"entry/k-ac573a06199ca0ed","state":{"route":"entry/k-ac573a06199ca0ed"},"node":{"id":"k-ac573a06199ca0ed","mode":"k","title":"爱国卫生运动","type":"概念与词义","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["社会治理"],"来源主题":["就业、社保与公共服务"],"资料类别":["非时政"]},"directorySummary":"2.爱国卫生运动\n爱国卫生运动是中国共产党于 1952 年发起的群众性卫生活动，是我国历史上持续时间\n最长的群众性运动，其核心要素体现为“爱国是核心、卫生是根本、运动是方式”。该运动\n由毛泽东等老一辈革命家倡导，周恩来担任首任中央防疫委员会主任并主持反细菌战防疫体\n系建设，初期以反细菌战和防疫工作为…","sources":[{"id":"ae9d233d249830ad","label":"爱国卫生运动","topic":"就业、社保与公共服务","category":"非时政","text":"2.爱国卫生运动\n爱国卫生运动是中国共产党于 1952 年发起的群众性卫生活动，是我国历史上持续时间\n最长的群众性运动，其核心要素体现为“爱国是核心、卫生是根本、运动是方式”。该运动\n由毛泽东等老一辈革命家倡导，周恩来担任首任中央防疫委员会主任并主持反细菌战防疫体\n系建设，初期以反细菌战和防疫工作为核心，后发展为涵盖城乡环境治理、卫生设施改善的\n系统性工程。\n70 年来，在党的领导下，爱国卫生运动坚持以人民健康为中心，坚持预防为主，为改\n变城乡环境卫生面貌、有效应对重大传染病疫情、提升社会健康治理水平发挥了重要作用。\n——《习近平总书记在爱国卫生运动开展 70 周年之际作出重要指示》","source":{"doc":"6cbfb01fe723bba64b75","first":42,"last":42,"page":42,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-ac573a06199ca0ed":[]}};
